CREATE TABLE factor_proposal_withdrawal (proposal_fingerprint TEXT PRIMARY KEY REFERENCES factor_proposal_snapshot, command_id UUID UNIQUE NOT NULL REFERENCES product_command_receipt DEFERRABLE INITIALLY DEFERRED);
